// Regenerate after a Fontsource update: node scripts/create-font-fallbacks.cjs
const fs = require("node:fs");
const path = require("node:path");
const root = path.join(__dirname, "..");
let css =
  "/* Generated by scripts/create-font-fallbacks.cjs. Unmodified Fontsource Carlito assets. */\n";
for (const [family, adjustment] of [
  ["Calibri", "100%"],
  ["Calibri Light", "98.8%"],
]) {
  for (const weight of [400, 700])
    for (const style of ["normal", "italic"]) {
      const source = fs.readFileSync(
        path.join(
          root,
          "node_modules/@fontsource/carlito",
          `${weight}${style === "italic" ? "-italic" : ""}.css`,
        ),
        "utf8",
      );
      for (const block of source.matchAll(/@font-face\s*\{([^}]+)\}/g)) {
        const filename = block[1].match(/files\/([^')]+\.woff2)/)[1];
        const range = block[1].match(/unicode-range:\s*([^;]+);/)[1];
        css += `\n@font-face {\n  font-family: "Slide Studio ${family}";\n  src: url("@fontsource/carlito/files/${filename}") format("woff2");\n  font-style: ${style};\n  font-weight: ${weight === 400 ? "300 400" : "700"};\n  font-display: block;\n  unicode-range: ${range};\n  size-adjust: ${adjustment};\n  ascent-override: 75%;\n  descent-override: 25%;\n  line-gap-override: 22.0703125%;\n}\n`;
      }
    }
}
fs.writeFileSync(path.join(root, "src/carlito-fallbacks.css"), css);
